contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 amount) public {
        require(target != address(0));
        require(target != address(this));

        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;

        uint256 beforeBal = c.balanceOf(target); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = c.balanceOf(target); if (__ESBMC_reverted()) return;

        assert(reverted && afterBal == beforeBal);
    }

    receive() external payable {}
}

