contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, uint256 amount) internal {
        vm.assume(target != address(0));
        vm.assume(target != address(this));
        try c.freezeAccount(target, true) {} catch { return; }
        uint256 beforeBal;
        try c.balanceOf(target) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool reverted;
        try c.transfer(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal;
        try c.balanceOf(target) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(reverted && afterBal == beforeBal);
    }

